export const getQuestionsByWeekENG7 = (weekNum) => {
  return QUESTION_BANK_ENG7.filter(q => q.week === Number(weekNum));
};

export const getFilteredQuestionsENG7 = ({ week, stage, difficulty, category }) => {
  return QUESTION_BANK_ENG7.filter(q => {
    if (week && q.week !== Number(week)) return false;
    if (stage && q.stage !== Number(stage)) return false;
    if (difficulty && q.difficulty !== difficulty) return false;
    if (category && q.category !== category) return false;
    return true;
  });
};
